def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [b for a, b in history]
    my = [a for a, b in history]

    opp_def = 0
    for x in opp:
        if x == 'D':
            opp_def += 1

    my_def = 0
    for x in my:
        if x == 'D':
            my_def += 1

    # Probe for an unconditional cooperator at round 11 (n=10)
    if n == 10 and opp_def == 0 and my_def == 0:
        return 'D'

    # Count consecutive opponent defections at the end
    consec_opp_def = 0
    for x in reversed(opp):
        if x == 'D':
            consec_opp_def += 1
        else:
            break

    # Switch to always defect if opponent is clearly an always-defector
    if consec_opp_def >= 5 and opp_def > n * 0.5:
        return 'D'

    # Pavlov core: win-stay, lose-shift
    last_my, last_opp = history[-1]
    if last_my == 'C' and last_opp == 'C':
        return 'C'
    elif last_my == 'D' and last_opp == 'C':
        return 'D'
    elif last_my == 'C' and last_opp == 'D':
        return 'D'
    elif last_my == 'D' and last_opp == 'D':
        return 'C'

    return 'C'
